<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch,nextTick} from 'vue';
import {api,message,uploadImage} from './api/platform';
import type {User,City,Spot,Folder,Favorite,Post,Profile} from './api/platform';
import type {Session,SessionItem,Preferences} from './types/chat';
import TravelConversation from './components/TravelConversation.vue';
import JourneyBoard from './components/JourneyBoard.vue';
import SceneryArt from './components/SceneryArt.vue';

const route=ref(location.hash.slice(2)||'home');
const page=computed(()=>route.value.split('/')[0]);
const user=ref<User|null>(null);const isAdmin=ref(false);const loading=ref(true);const notice=ref('');const error=ref('');
const busy=ref(false);const saving=ref(false);const widget=ref(false);const authOpen=ref(false);const register=ref(false);
const credentials=ref({email:'',password:'',name:''});const currentCity=ref('杭州');const locating=ref(false);
const catalog=ref<City[]>([]);const spots=ref<Record<string,Spot[]>>({});const loadingCities=ref<string[]>([]);const failedCities=ref<string[]>([]);const brokenImages=ref<string[]>([]);
const search=ref('');const theme=ref('全部');const seasonOnly=ref(false);const nearby=ref(false);const feedback=ref<Record<string,string>>({});
const themes=['全部','自然山水','历史文化','城市漫步','美食慢游','海滨休闲'];
const cityGroups:Record<string,string[]>={'自然山水':['杭州','南京','三亚','昆明','大理','丽江','桂林','黄山','张家界'],'历史文化':['北京','南京','西安','杭州','苏州','洛阳','厦门'],'城市漫步':['上海','重庆','成都','苏州','长沙','青岛','哈尔滨'],'美食慢游':['成都','重庆','西安','长沙','厦门','昆明'],'海滨休闲':['三亚','厦门','青岛']};
const visibleCities=computed(()=>catalog.value.filter(c=>(!search.value||[c.city,c.description,...c.tags].join(' ').includes(search.value))&&(theme.value==='全部'||cityGroups[theme.value]?.includes(c.city))&&(!seasonOnly.value||c.seasonal)&&(!nearby.value||c.city===currentCity.value)&&feedback.value['city:'+c.city]!=='hide').sort((a,b)=>recommendationScore(b)-recommendationScore(a)));
function recommendationScore(city:City){
 let score=city.seasonal?10:0;const mark=feedback.value['city:'+city.city];if(mark==='want')score+=12;if(mark==='visited')score-=10;
 const interests=user.value?.profile.interests||[];
 const groups:Record<string,string[]>={自然:['杭州','南京','三亚'],文化:['北京','南京','西安','杭州'],历史:['北京','南京','西安'],美食:['成都','重庆','西安'],艺术:['上海','北京'],亲子:['成都','三亚']};
 for(const tag of interests)if(groups[tag]?.includes(city.city))score+=4;
 return score;
}
let cityObserver:IntersectionObserver|undefined;
async function observeCities(){await nextTick();if(!cityObserver)cityObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){const city=(entry.target as HTMLElement).dataset.city;if(city)void loadCity(city);cityObserver?.unobserve(entry.target)}},{rootMargin:'180px'});for(const element of document.querySelectorAll('[data-city]'))cityObserver.observe(element)}
watch(visibleCities,()=>void observeCities());
const heroImage=computed(()=>spots.value[currentCity.value]?.find(s=>s.image)?.image||spots.value['杭州']?.find(s=>s.image)?.image);
const detailCity=computed(()=>decodeURIComponent(route.value.split('/')[1]||currentCity.value));
const sessions=ref<SessionItem[]>([]);const session=ref<Session|null>(null);const provider=ref('');const mobileWorkTab=ref('plan');
const folders=ref<Folder[]>([]);const favorites=ref<Favorite[]>([]);const posts=ref<Post[]>([]);const feed=ref<Post[]>([]);const folderName=ref('');const activeFolder=ref('');const selectedFavorites=ref<string[]>([]);const spaceTab=ref('journeys');
const favoriteOpen=ref(false);const favoriteFolder=ref('');const pendingFavorite=ref<{kind:string;city:string;name:string;target:string;image?:string}>();
const editor=ref(false);const form=ref<Preferences>({});const profile=ref<Profile&{name:string}>({name:''});
const postOpen=ref(false);const editingPost=ref('');const uploadProgress=ref<number|null>(null);const photoError=ref('');const uploadQueue=ref<File[]>([]);
const postForm=ref({title:'',body:'',city:'杭州',travel_date:'',visibility:'private',images:[] as string[]});
const shared=ref<{title:string;plan:Session['plan']}|null>(null);const shareOpen=ref(false);const shareUrl=ref('');
const postDetail=ref<Post|null>(null);const reportReason=ref('');const adminQueue=ref<{posts:Post[];reports:{id:string;post_id:string;title:string;reason:string}[]}>({posts:[],reports:[]});
const searchResults=ref<Spot[]>([]);const searchLoading=ref(false);const searchError=ref('');const searchPage=ref(1);const searchMore=ref(false);
let searchTimer:ReturnType<typeof setTimeout>|undefined;let searchRequest=0;
async function searchPlaces(more=false){
 const q=search.value.trim();const request=++searchRequest;if(!q){searchResults.value=[];searchLoading.value=false;return}
 searchLoading.value=true;searchError.value='';const number=more?searchPage.value+1:1;
 try{const result=await api<{spots:Spot[];has_more:boolean}>('/discover/search?q='+encodeURIComponent(q)+'&page='+number);if(request!==searchRequest)return;searchResults.value=more?[...searchResults.value,...result.spots]:result.spots;searchPage.value=number;searchMore.value=result.has_more}catch(e){if(request===searchRequest)searchError.value=e instanceof Error?e.message:String(e)}finally{if(request===searchRequest)searchLoading.value=false}
}
watch(search,()=>{if(searchTimer)clearTimeout(searchTimer);searchRequest++;searchResults.value=[];searchError.value='';if(!search.value.trim()){searchLoading.value=false;return}searchLoading.value=true;searchTimer=setTimeout(()=>void searchPlaces(),450)});
const floating=ref<{x:number;y:number}|null>(null);let dragCleanup:(()=>void)|undefined;let suppressClickUntil=0;
const floatingStyle=computed(()=>floating.value?{left:floating.value.x+'px',top:floating.value.y+'px',right:'auto',bottom:'auto'}:{});
function clampFloating(){if(!floating.value)return;const element=document.querySelector<HTMLElement>(widget.value?'.assistant-widget':'.assistant-launcher');if(!element)return;const rect=element.getBoundingClientRect();floating.value={x:Math.max(8,Math.min(floating.value.x,innerWidth-rect.width-8)),y:Math.max(8,Math.min(floating.value.y,innerHeight-rect.height-8))}}
function resetFloating(){floating.value=null;localStorage.removeItem('travel-assistant-position')}
function startDrag(event:PointerEvent){
 if(event.button!==0||(event.target as HTMLElement).closest('input,textarea,select')||((event.target as HTMLElement).closest('button')&&!((event.currentTarget as HTMLElement).classList.contains('assistant-launcher'))))return;
 dragCleanup?.();const element=document.querySelector<HTMLElement>(widget.value?'.assistant-widget':'.assistant-launcher');if(!element)return;
 const rect=element.getBoundingClientRect();const x=event.clientX,y=event.clientY;let moved=false;
 const move=(e:PointerEvent)=>{if(Math.abs(e.clientX-x)+Math.abs(e.clientY-y)<5&&!moved)return;moved=true;floating.value={x:rect.left+e.clientX-x,y:rect.top+e.clientY-y};clampFloating();e.preventDefault()};
 const end=()=>{if(moved){suppressClickUntil=Date.now()+300;localStorage.setItem('travel-assistant-position',JSON.stringify(floating.value))}window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',end);dragCleanup=undefined};
 window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',end);window.addEventListener('pointercancel',end);dragCleanup=end;
}
async function launcherClick(){if(Date.now()<suppressClickUntil)return;await openAssistant()}
watch(widget,async()=>{await nextTick();clampFloating()});
const knowledgeDocuments=ref<{id:string;title:string;city:string;source:string;characters:number}[]>([]);
const knowledgeForm=ref({title:'',city:'',source:'',url:'',body:''});
async function loadKnowledge(){knowledgeDocuments.value=await api('/knowledge/documents')}
async function addKnowledge(){await task(async()=>{await api('/knowledge/documents','POST',knowledgeForm.value);knowledgeForm.value={title:'',city:'',source:'',url:'',body:''};await loadKnowledge();tell('资料已分块并加入检索索引')})}
async function deleteKnowledge(id:string){if(!window.confirm('从知识库中移除此资料及索引？'))return;await task(async()=>{await api('/knowledge/documents/'+id,'DELETE');await loadKnowledge()})}
async function importKnowledge(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>300000){error.value='知识资料文件请控制在300KB以内';return}knowledgeForm.value.body=await file.text();if(!knowledgeForm.value.title)knowledgeForm.value.title=file.name.replace(/\.(md|txt)$/i,'')}
const ready=computed(()=>session.value&&['departure_city','destination','budget','num_travelers','start_date','days'].every(k=>(session.value!.preferences as Record<string,unknown>)[k]));
const statusName:Record<string,string>={draft:'草稿 / 私人足迹',pending:'审核中',approved:'已公开',rejected:'审核未通过',hidden:'已下架'};
const shareSession=computed<Session|null>(()=>shared.value?{id:'shared',title:shared.value.title,revision:0,preferences:shared.value.plan?.preferences||{},plan:shared.value.plan,versions:[],messages:[],trace:[]}:null);

let pendingTasks=0;
async function task(action:()=>Promise<void>){pendingTasks++;saving.value=true;error.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{pendingTasks--;saving.value=pendingTasks>0}}
function tell(text:string){notice.value=text;window.setTimeout(()=>{if(notice.value===text)notice.value=''},5000)}
function go(path:string){location.hash='/'+path}
function scrollDestinations(){document.getElementById('destinations')?.scrollIntoView({behavior:'smooth'})}
async function onRoute(){route.value=location.hash.slice(2)||'home';error.value='';if(page.value==='destination')await loadCity(detailCity.value);if(page.value==='community')await task(loadFeed);if(page.value==='space'&&user.value)await task(refreshPersonal);if(page.value==='admin'&&isAdmin.value)await task(loadAdmin);if(page.value==='share'){shared.value=null;await task(async()=>{shared.value=await api('/shares/'+route.value.split('/')[1])})}window.scrollTo({top:0});if(page.value==='home')void observeCities()}
async function loadCity(city:string){if(spots.value[city]||loadingCities.value.includes(city))return;loadingCities.value.push(city);try{const data=await api<{spots:Spot[];mode:string}>('/discover/spots?city='+encodeURIComponent(city));spots.value={...spots.value,[city]:data.spots};if(data.mode==='mock')failedCities.value.push(city)}catch{failedCities.value.push(city)}finally{loadingCities.value=loadingCities.value.filter(c=>c!==city)}}
async function refreshSessions(){sessions.value=await api('/chat/sessions')}
async function remember(s:Session){session.value=s;localStorage.setItem('travel-current-session',s.id);await refreshSessions()}
async function ensureSession(){if(session.value)return;await refreshSessions();const id=localStorage.getItem('travel-current-session');await remember(id&&sessions.value.some(s=>s.id===id)?await api('/chat/sessions/'+id):await api('/chat/sessions','POST',{}))}
async function newJourney(){if(busy.value)return;await task(async()=>{await remember(await api('/chat/sessions','POST',{}));if(page.value==='workspace'){mobileWorkTab.value='chat';widget.value=false}else widget.value=true})}
async function openAssistant(city?:string,selected:string[]=[]){
 if(busy.value)return;widget.value=true;busy.value=Boolean(city);
 try{await task(async()=>{await ensureSession();if(city){const previous=session.value;session.value=await api('/chat/sessions','POST',{});try{await remember(await message(session.value!,'想围绕'+city+'规划旅行',{destination:city,...(selected.length?{selected_spots:selected}:{})},false))}catch(e){session.value=previous;throw e}}})}finally{busy.value=false}
}
async function send(text:string,generate=false){if(busy.value)return;busy.value=true;error.value='';try{await ensureSession();const planning=generate||Boolean(session.value?.plan&&/酒店|第[一二三四五六七八九十0-9]+天|预算.*(?:改|调)|(?:增加|减少|修改|更换|调整).*(?:景点|行程|活动)/.test(text));await remember(await message(session.value!,text,undefined,planning))}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function generate(){if(!ready.value)return;await send('请根据已确认的需求生成完整行程',true);if(session.value?.plan&&!error.value){widget.value=false;go('workspace');mobileWorkTab.value='plan'}}
function editPreferences(){form.value={...session.value?.preferences};editor.value=true}
async function savePreferences(){if(!session.value)return;busy.value=true;try{const patch=Object.fromEntries(Object.entries(form.value).filter(([,v])=>v!==''&&v!==null&&v!==undefined));await remember(await message(session.value,'已确认旅行需求',patch as Preferences,false));editor.value=false}catch(e){error.value=String(e)}finally{busy.value=false}}
async function selectJourney(id:string){if(busy.value)return;await task(async()=>{await remember(await api('/chat/sessions/'+id));widget.value=false;go('workspace')})}
async function restore(version:number){await task(async()=>{const s=session.value!;await remember(await api(`/chat/sessions/${s.id}/restore/${version}`,'POST',{message:'恢复方案',revision:s.revision}))})}
async function renameJourney(item:SessionItem){const title=window.prompt('行程名称',item.title);if(!title?.trim())return;await task(async()=>{const s=await api<Session>('/chat/sessions/'+item.id,'PATCH',{title,revision:item.revision});if(session.value?.id===item.id)session.value=s;await refreshSessions()})}
async function deleteJourney(item:SessionItem){if(!window.confirm('删除此行程及其分享？此操作无法撤销。'))return;await task(async()=>{await api('/chat/sessions/'+item.id,'DELETE');if(session.value?.id===item.id)session.value=null;await refreshSessions()})}
async function refreshPersonal(){if(!user.value)return;[folders.value,favorites.value,posts.value,feedback.value]=await Promise.all([api<Folder[]>('/folders'),api<Favorite[]>('/favorites'),api<Post[]>('/posts?mine=true'),api<Record<string,string>>('/feedback')]);await refreshSessions()}
async function authenticate(){await task(async()=>{await api('/account/'+(register.value?'register':'login'),'POST',{...credentials.value,name:credentials.value.name||'旅行者'});credentials.value.password='';const me=await api<{user:User;is_admin:boolean}>('/account/me');user.value=me.user;isAdmin.value=me.is_admin;profile.value={...user.value.profile,name:user.value.name};authOpen.value=false;await refreshPersonal();tell('欢迎回来，旅行已为你保存')})}
async function logout(){if(busy.value)return;await task(async()=>{await api('/account/logout','POST',{});user.value=null;isAdmin.value=false;session.value=null;sessions.value=[];favorites.value=[];folders.value=[];posts.value=[];feedback.value={};localStorage.removeItem('travel-current-session');widget.value=false;go('home');tell('已退出登录')})}
function needLogin(){if(user.value)return true;authOpen.value=true;return false}
async function saveProfile(){await task(async()=>{user.value=await api('/account/profile','PUT',profile.value);tell('偏好已保存，将用于新建行程')})}
async function createFolder(){if(!folderName.value.trim())return;await task(async()=>{const folder=await api<Folder>('/folders','POST',{name:folderName.value});folders.value.push(folder);favoriteFolder.value=folder.id;folderName.value=''})}
async function removeFolder(id:string){if(!window.confirm('删除收藏夹及其中的收藏？'))return;await task(async()=>{await api('/folders/'+id,'DELETE');await refreshPersonal();activeFolder.value=''})}
async function startFavorite(kind:string,city:string,name:string,target:string,image?:string){if(!needLogin())return;pendingFavorite.value={kind,city,name,target,image};if(!folders.value.length){await task(async()=>{const folder=await api<Folder>('/folders','POST',{name:'想去的地方'});folders.value=[folder]})}favoriteFolder.value=folders.value[0]?.id||'';favoriteOpen.value=true}
async function saveFavorite(){if(!pendingFavorite.value)return;await task(async()=>{await api('/favorites','POST',{...pendingFavorite.value,folder_id:favoriteFolder.value});await refreshPersonal();favoriteOpen.value=false;tell('已加入收藏夹')})}
async function removeFavorite(id:string){await task(async()=>{await api('/favorites/'+id,'DELETE');await refreshPersonal()})}
async function planFavorites(){const list=favorites.value.filter(x=>selectedFavorites.value.includes(x.id));if(!list.length){tell('先选择想安排的景点');return}if(new Set(list.map(x=>x.city)).size>1){error.value='请先选择同一城市的景点，跨城行程请在对话中补充';return}await openAssistant(list[0].city,list.filter(x=>x.kind==='spot').map(x=>x.name))}
async function mark(city:string,value:string){if(!needLogin())return;await task(async()=>{await api('/feedback','POST',{target:'city:'+city,value});feedback.value={...feedback.value,['city:'+city]:value};tell(value==='hide'?'已减少这类目的地展示':'旅行偏好已记录')})}
async function resetFeedback(target:string){await task(async()=>{await api('/feedback/'+encodeURIComponent(target),'DELETE');await refreshPersonal()})}
function toggleInterest(value:string){const list=profile.value.interests||[];profile.value.interests=list.includes(value)?list.filter(x=>x!==value):[...list,value]}
async function locate(){locating.value=true;error.value='';if(!navigator.geolocation){error.value='浏览器不支持定位，请手动选择城市';locating.value=false;return}navigator.geolocation.getCurrentPosition(async pos=>{try{const value=await api<{city:string}>('/discover/location','POST',{longitude:pos.coords.longitude,latitude:pos.coords.latitude});currentCity.value=value.city;await loadCity(value.city);tell('已更新当前城市：'+value.city)}catch(e){error.value=String(e)}finally{locating.value=false}},()=>{error.value='未获得定位，可手动选择城市';locating.value=false},{enableHighAccuracy:false,timeout:10000,maximumAge:300000})}
async function loadFeed(){feed.value=await api('/posts')}
function writePost(post?:Post){if(!needLogin())return;editingPost.value=post?.id||'';postForm.value=post?{title:post.title,body:post.body,city:post.city,travel_date:post.travel_date||'',visibility:post.visibility,images:[...post.images]}:{title:'',body:'',city:currentCity.value,travel_date:'',visibility:'private',images:[]};photoError.value='';postOpen.value=true}
async function uploadFiles(event:Event){const input=event.target as HTMLInputElement;uploadQueue.value=Array.from(input.files||[]);input.value='';await retryUpload()}
async function retryUpload(){photoError.value='';while(uploadQueue.value.length){if(postForm.value.images.length>=9){photoError.value='最多添加9张照片';return}const file=uploadQueue.value[0];if(file.size>8*1024*1024){photoError.value='单张图片不能超过8MB';return}uploadProgress.value=0;try{const result=await uploadImage(file,p=>uploadProgress.value=p);postForm.value.images.push(result.id);uploadQueue.value.shift()}catch(e){photoError.value=String(e);break}finally{uploadProgress.value=null}}}
async function savePost(submit:boolean){if(!postForm.value.title.trim()||!postForm.value.body.trim()||!postForm.value.city.trim()){error.value='请填写标题、城市和旅行记录';return}await task(async()=>{const data={...postForm.value,travel_date:postForm.value.travel_date||null,submit};await api('/posts'+(editingPost.value?'/'+editingPost.value:''),editingPost.value?'PUT':'POST',data);postOpen.value=false;await refreshPersonal();tell(submit&&data.visibility==='public'?'已提交审核，通过后公开展示':'旅行足迹已保存')})}
async function deletePost(id:string){if(!window.confirm('删除这篇旅行足迹？'))return;await task(async()=>{await api('/posts/'+id,'DELETE');await refreshPersonal()})}
async function openPost(id:string){await task(async()=>{postDetail.value=await api('/posts/'+id);reportReason.value=''})}
async function report(){if(!needLogin()||!postDetail.value)return;await task(async()=>{await api('/posts/'+postDetail.value!.id+'/report','POST',{reason:reportReason.value});reportReason.value='';tell('举报已提交，等待管理员处理')})}
async function showShare(){if(!needLogin())return;shareUrl.value='';shareOpen.value=true}
async function createShare(){if(!session.value)return;await task(async()=>{const result=await api<{path:string}>(`/chat/sessions/${session.value!.id}/share`,'POST',{});shareUrl.value=location.origin+result.path;tell('分享链接已生成，有效期7天')})}
async function revokeShare(){if(!session.value)return;await task(async()=>{await api(`/chat/sessions/${session.value!.id}/share`,'DELETE');shareUrl.value='';tell('此行程的分享链接已撤销')})}
async function copyShare(){try{await navigator.clipboard.writeText(shareUrl.value);tell('链接已复制')}catch{tell('请手动复制链接')}}
async function loadAdmin(){adminQueue.value=await api('/admin/queue');await loadKnowledge()}
async function review(id:string,decision:string){await task(async()=>{await api('/admin/posts/'+id+'/review','POST',{decision,note:'管理员审核'});await loadAdmin();tell('审核结果已保存')})}
onMounted(async()=>{window.addEventListener('hashchange',onRoute);window.addEventListener('resize',clampFloating);try{const saved=JSON.parse(localStorage.getItem('travel-assistant-position')||'null');if(saved&&Number.isFinite(saved.x)&&Number.isFinite(saved.y))floating.value=saved}catch{}try{const me=await api<{user:User|null;is_admin:boolean}>('/account/me');user.value=me.user;isAdmin.value=me.is_admin;if(user.value)profile.value={...user.value.profile,name:user.value.name};catalog.value=await api('/discover/catalog');provider.value=(await api<{provider:string}>('/chat/config')).provider;await refreshSessions();if(user.value)await refreshPersonal();if(page.value==='workspace')await ensureSession();await onRoute();void loadCity(currentCity.value);void observeCities()}catch(e){error.value=String(e)}finally{loading.value=false}});
onUnmounted(()=>{window.removeEventListener('hashchange',onRoute);window.removeEventListener('resize',clampFloating);dragCleanup?.();cityObserver?.disconnect();if(searchTimer)clearTimeout(searchTimer)});
</script>

<template>
 <div class="travel-site" :class="{'workspace-page':page==='workspace'}">
 <header class="site-header"><a href="#/home" class="site-logo"><span>↗</span>山与行<small>ROAM CHINA</small></a><nav aria-label="主导航"><a href="#/home" :class="{active:page==='home'||page==='destination'}">发现好风景</a><a href="#/community" :class="{active:page==='community'}">旅行故事</a><button :class="{active:page==='space'}" @click="user?go('space'):(authOpen=true)">我的空间</button><a v-if="isAdmin" href="#/admin">内容管理</a></nav><div class="header-actions"><label class="city-picker">⌖ <select v-model="currentCity" aria-label="当前城市" @change="loadCity(currentCity)"><option v-for="c in catalog" :value="c.city">{{c.city}}</option><option v-if="!catalog.some(c=>c.city===currentCity)">{{currentCity}}</option></select></label><button v-if="!user" class="outline" @click="authOpen=true">登录 / 注册</button><button v-else class="avatar-button" @click="go('space')" :aria-label="user.name+'的个人空间'">{{user.name.slice(0,1)}}</button></div></header>
 <div v-if="error" class="global-message error" role="alert"><span>{{error}}</span><button aria-label="关闭错误提示" @click="error=''">×</button></div><div v-if="notice" class="global-message success" role="status">{{notice}}</div>
 <div v-if="loading" class="loading-page">正在寻找下一段好风景…</div>
 <main v-else-if="page==='home'" class="discovery-home">
  <section class="discovery-hero"><img v-if="heroImage&&!brokenImages.includes(heroImage)" :src="heroImage" @error="brokenImages.push(heroImage)" alt="国内景点照片，非当前实景"/><SceneryArt v-else theme="garden" label="山水旅行示意插画"/><div class="hero-shade"></div><div class="hero-copy"><span class="hero-kicker">FOLLOW THE SEASON. FIND YOUR WAY.</span><h1>好风景，<br/>值得慢慢遇见。</h1><p>从身边的山水，到心里的远方。<br/>发现中国的下一站，把向往变成行程。</p><div class="hero-search"><span>⌕</span><input v-model="search" aria-label="搜索目的地或景点" placeholder="想去哪里？搜城市、景点或旅行灵感" @keydown.enter="scrollDestinations()"/><button @click="search.trim()?scrollDestinations():go('destination/'+encodeURIComponent(currentCity))">去看看 ↗</button></div></div><div class="hero-caption"><span>⌖ {{currentCity}} · 国内旅行灵感</span><small>{{heroImage?'图片来源：高德地图 · 非实时实景':'旅行示意插画'}}</small></div><span class="hero-side-note">A LITTLE CLOSER TO THE WORLD</span></section>
  <section class="discovery-section" id="destinations"><div class="section-title"><div><span class="small-label">A SEASON TO EXPLORE</span><h2>发现，正当时<span>把喜欢的地方，放进下一次出发。</span></h2></div><div class="inline-row"><button class="text-button" @click="locate" :disabled="locating">{{locating?'定位中…':'⌖ 定位到我的城市'}}</button><label><input type="checkbox" v-model="seasonOnly"/> 当季优先</label><label><input type="checkbox" v-model="nearby"/> 当前城市</label></div></div><div class="theme-tabs"><button v-for="t in themes" :class="{active:theme===t}" @click="theme=t">{{t}}</button><input v-model="search" placeholder="搜索城市或景点" aria-label="筛选目的地"/></div><section v-if="search.trim()" class="live-search-section"><div class="section-title"><div><span class="small-label">SEARCH PLACES ACROSS CHINA</span><h2>“{{search}}”的地点结果</h2></div><span class="muted">高德实时检索 · 不限精选城市</span></div><p v-if="searchLoading" class="muted">正在寻找相关景点…</p><div v-if="searchError" class="inline-error">{{searchError}} <button @click="searchPlaces()">重试</button></div><div class="destination-grid"><article v-for="spot in searchResults" :key="spot.poi_id||spot.name" class="destination-card"><button class="destination-image" @click="go('destination/'+encodeURIComponent(spot.city||currentCity))"><img v-if="spot.image&&!brokenImages.includes(spot.image)" :src="spot.image" :alt="spot.name" @error="brokenImages.push(spot.image!)"/><SceneryArt v-else theme="garden" :label="spot.name+'示意插画'"/><span class="city-image-label">{{spot.image?'高德地点照片':'示意插画'}}</span></button><div class="destination-content"><div><h3 class="search-place-title">{{spot.name}}</h3><button class="save-heart" :aria-label="'收藏'+spot.name" @click="startFavorite('spot',spot.city||currentCity,spot.name,'poi:'+(spot.poi_id||spot.name),spot.image)">♡</button></div><p>{{spot.city}} · {{spot.subtitle}}</p><small>{{spot.tag}}</small><div class="card-feedback"><button @click="openAssistant(spot.city||currentCity,[spot.name])">围绕这里规划 ↗</button><a :href="'https://uri.amap.com/search?keyword='+encodeURIComponent(spot.name)+'&src=roam'" target="_blank" rel="noopener">查看地图</a></div></div></article></div><p v-if="!searchLoading&&!searchError&&!searchResults.length" class="muted">没有找到相关景点，试试更具体的城市或景点名称。</p><button v-if="searchMore&&!searchLoading" class="load-more" @click="searchPlaces(true)">加载更多地点</button></section><h3 v-if="search.trim()&&visibleCities.length" class="muted">相关精选目的地</h3><div class="destination-grid"><article v-for="(c,i) in visibleCities" :key="c.city" :data-city="c.city" class="destination-card"><button class="destination-image" @click="go('destination/'+encodeURIComponent(c.city))"><img v-if="spots[c.city]?.find(s=>s.image)?.image&&!brokenImages.includes(spots[c.city].find(s=>s.image)!.image!)" :src="spots[c.city].find(s=>s.image)!.image" :alt="c.city+'景点资料照片'" loading="lazy" @error="brokenImages.push(spots[c.city].find(s=>s.image)!.image!)"/><SceneryArt v-else :theme="i%2?'city':'garden'" :label="c.city+'示意插画'"/><span class="city-image-label">{{spots[c.city]?.some(s=>s.image)?'高德景点照片':'示意插画'}}</span><span class="season-chip">{{c.seasonal?'当季探索':'旅行灵感'}}</span></button><div class="destination-content"><div><h3><a :href="'#/destination/'+encodeURIComponent(c.city)">{{c.city}}</a></h3><button class="save-heart" :aria-label="'收藏'+c.city" @click="startFavorite('city',c.city,c.city,'city:'+c.city,spots[c.city]?.find(s=>s.image)?.image)">♡</button></div><p>{{c.description}}</p><small>{{c.tags.join(' / ')}}</small><div class="card-feedback"><button @click="mark(c.city,'want')">{{feedback['city:'+c.city]==='want'?'✓ 想去':'想去'}}</button><button @click="mark(c.city,'visited')">{{feedback['city:'+c.city]==='visited'?'✓ 去过':'去过'}}</button><button @click="mark(c.city,'hide')">不感兴趣</button></div></div></article></div><div v-if="!visibleCities.length" class="empty-state"><h3>还没找到合适的风景</h3><p>试试其他关键词、取消筛选，或让旅行助手帮你安排。</p><button @click="search='';theme='全部';nearby=false;seasonOnly=false">清除筛选</button></div></section>
  <section class="weekend-banner"><span class="small-label">MAKE ROOM FOR A LITTLE ESCAPE</span><h2>不用很远，也能换个心情。</h2><p>一个周末、一段漫步，把想去的地方交给旅行助手。</p><button class="primary" @click="openAssistant(currentCity)">安排一次轻旅行 ↗</button><span class="banner-art">↗</span></section>
  <footer class="site-footer"><b>山与行 ROAM CHINA</b><p>推荐结合月份、兴趣和你的反馈，不代表即时花期或热度。景点资料标注来源，开放与预约以景区公告为准。</p><small>发现好风景，也发现自己的旅行方式。</small></footer>
 </main>

 <main v-else-if="page==='destination'" class="destination-detail page-container"><button class="text-button" @click="go('home')">← 返回发现</button><div class="detail-heading"><div><span class="small-label">A PLACE TO SLOW DOWN</span><h1>{{detailCity}}，值得一程</h1><p>沿着喜欢的风景，安排自己的旅行节奏。</p></div><button class="primary" @click="openAssistant(detailCity)">围绕这里规划旅行 ↗</button></div><div v-if="loadingCities.includes(detailCity)" class="empty-state">正在查询景点资料…</div><div v-else-if="!spots[detailCity]?.length" class="empty-state"><h3>暂时没有景点资料</h3><button @click="delete spots[detailCity];loadCity(detailCity)">重新获取</button></div><div class="detail-spots"><article v-for="spot in spots[detailCity]" class="detail-spot"><div class="detail-photo"><img v-if="spot.image&&!brokenImages.includes(spot.image)" :src="spot.image" :alt="spot.name" @error="brokenImages.push(spot.image!)"/><SceneryArt v-else theme="garden" :label="spot.name+'示意插画'"/><small>{{spot.image?'照片来源：'+spot.source+'（非实时实景）':'示意插画'}}</small></div><div><span class="small-label">{{spot.tag}}</span><h2>{{spot.name}}</h2><p>{{spot.subtitle}}</p><p>{{spot.seasonal?'适合本月探索，实际景色受天气影响。':'旅行灵感参考，可结合季节与天气安排。'}}</p><div class="inline-row"><button @click="startFavorite('spot',detailCity,spot.name,'spot:'+detailCity+':'+spot.name,spot.image)">♡ 收藏景点</button><a :href="'https://uri.amap.com/search?keyword='+encodeURIComponent(spot.name)+'&city='+encodeURIComponent(detailCity)+'&src=roam'" target="_blank" rel="noopener">高德地图 ↗</a></div><p class="muted">地点资料：{{spot.source}}。开放、门票和预约请查询景区公告。</p></div></article></div></main>

 <main v-else-if="page==='workspace'" class="workspace-shell"><div class="work-top"><button class="text-button" @click="go('home')">← 返回发现</button><span>{{session?.title||'新的旅行'}} <small>· 自动保存</small></span><button @click="newJourney">＋ 新旅行</button></div><div class="mobile-work-tabs"><button :class="{active:mobileWorkTab==='chat'}" @click="mobileWorkTab='chat'">旅行对话</button><button :class="{active:mobileWorkTab==='plan'}" @click="mobileWorkTab='plan'">行程方案</button></div><div class="new-workspace"><aside class="journey-sidebar"><h3>我的旅行</h3><button v-for="s in sessions" :class="{active:s.id===session?.id}" @click="selectJourney(s.id)"><b>{{s.title}}</b><small>{{new Date(s.updated).toLocaleDateString()}}</small></button><p class="muted">{{user?'行程已保存在你的账户':'游客行程仅当前浏览器可访问，登录后可接续保存'}}</p></aside><TravelConversation :class="{'mobile-hidden':mobileWorkTab!=='chat'}" :session="session" :busy="busy" @send="send" @edit="editPreferences" @generate="generate"/><JourneyBoard v-if="session" :class="{'mobile-hidden':mobileWorkTab!=='plan'}" :session="session" :busy="busy" @send="text=>send(text,true)" @restore="restore" @share="showShare" @error="text=>error=text"/><div v-else class="empty-state"><h2>选择一段行程，或开始新的旅行</h2><button class="primary" @click="newJourney">开始规划</button></div></div></main>

 <main v-else-if="page==='space'" class="page-container personal-space"><div class="space-heading"><div class="profile-avatar">{{user?.name.slice(0,1)}}</div><div><span class="small-label">YOUR TRAVEL JOURNAL</span><h1>{{user?.name||'我的空间'}}</h1><p>收藏喜欢的风景，留住自己的旅程。</p></div><button class="text-button" @click="logout">退出登录</button></div><div v-if="!user" class="empty-state"><h3>登录后开启个人旅行空间</h3><button class="primary" @click="authOpen=true">登录 / 注册</button></div><template v-else><div class="space-tabs"><button v-for="item in [{id:'journeys',name:'我的行程'},{id:'favorites',name:'收藏夹'},{id:'posts',name:'旅行足迹'},{id:'profile',name:'旅行偏好'}]" :class="{active:spaceTab===item.id}" @click="spaceTab=item.id">{{item.name}}</button></div>
  <section v-if="spaceTab==='journeys'"><div class="section-title"><h2>每一次出发，都有迹可循</h2><button class="primary" @click="newJourney">＋ 规划新旅行</button></div><div class="personal-grid"><article v-for="s in sessions" class="personal-card"><span class="small-label">YOUR JOURNEY</span><h3>{{s.title}}</h3><p>{{new Date(s.updated).toLocaleString()}} · {{s.revision}}次更新</p><button class="primary" @click="selectJourney(s.id)">继续规划 ↗</button><div class="inline-row"><button class="text-button" @click="renameJourney(s)">重命名</button><button class="text-button danger" @click="deleteJourney(s)">删除</button></div></article></div><p v-if="!sessions.length" class="empty-state">还没有行程，先从一处喜欢的风景开始吧。</p></section>
  <section v-if="spaceTab==='favorites'"><div class="section-title"><div><h2>把喜欢的地方，存起来</h2><p class="muted">勾选同一城市的景点，让助手帮你串成行程。</p></div><button class="primary" @click="planFavorites">从收藏规划 ↗</button></div><div class="folder-bar"><button :class="{active:!activeFolder}" @click="activeFolder=''">全部收藏</button><span v-for="f in folders"><button :class="{active:activeFolder===f.id}" @click="activeFolder=f.id">{{f.name}}</button><button class="text-button" :aria-label="'删除收藏夹'+f.name" @click="removeFolder(f.id)">×</button></span><input v-model="folderName" placeholder="新收藏夹名称" aria-label="新收藏夹名称" maxlength="30"/><button @click="createFolder">＋ 创建</button></div><div class="personal-grid"><article v-for="fav in favorites.filter(f=>!activeFolder||f.folder_id===activeFolder)" class="personal-card"><label class="favorite-select"><input type="checkbox" :value="fav.id" v-model="selectedFavorites"/> {{fav.city}}</label><h3>{{fav.name}}</h3><p>{{folders.find(f=>f.id===fav.folder_id)?.name}}</p><button @click="fav.kind==='post'?openPost(fav.target.replace('post:','')):go('destination/'+encodeURIComponent(fav.city))">查看详情</button><button class="text-button" @click="removeFavorite(fav.id)">取消收藏</button></article></div><p v-if="!favorites.length" class="empty-state">还没有收藏，发现页上的 ♡ 可以帮你留住灵感。</p></section>
  <section v-if="spaceTab==='posts'"><div class="section-title"><div><h2>我的旅行足迹</h2><p class="muted">去过 {{new Set(posts.map(p=>p.city)).size}} 座城市 · {{posts.length}} 篇记录</p></div><button class="primary" @click="writePost()">＋ 记录一次旅行</button></div><div class="personal-grid"><article v-for="post in posts" class="personal-card post-card"><img v-if="post.images.length" :src="'/api/media/'+post.images[0]+'?thumb=true'" :alt="post.title"/><span class="status-badge">{{statusName[post.status]}}</span><h3>{{post.title}}</h3><p>{{post.city}} · {{post.travel_date||'未填写旅行日期'}}</p><p>{{post.body.slice(0,90)}}</p><button @click="writePost(post)">编辑</button><button class="text-button danger" @click="deletePost(post.id)">删除</button></article></div><p v-if="!posts.length" class="empty-state">上传几张照片，记下这次旅行的心情。</p></section>
  <form v-if="spaceTab==='profile'" class="profile-form" @submit.prevent="saveProfile"><div><span class="small-label">MAKE IT PERSONAL</span><h2>更懂你的旅行方式</h2><p>这些偏好将带入新行程，每次出行都可以单独调整。</p></div><div class="form-grid"><label>昵称<input v-model="profile.name" required maxlength="30"/></label><label>常用出发城市<input v-model="profile.departure_city" maxlength="30"/></label><label>总预算（元）<input type="number" v-model.number="profile.budget" min="1" max="1000000"/></label><label>常见出行人数<input type="number" v-model.number="profile.num_travelers" min="1" max="10"/></label><label>旅行节奏<select v-model="profile.pace"><option>轻松</option><option>适中</option><option>紧凑</option></select></label><label>交通偏好<select v-model="profile.transport"><option>高铁优先</option><option>飞机优先</option><option>自驾</option></select></label><label>步行强度<select v-model="profile.walking"><option>少走路</option><option>适中</option><option>喜欢徒步</option></select></label></div><label>喜欢的体验<div class="interest-tags"><button type="button" v-for="tag in ['自然','美食','文化','历史','艺术','亲子','摄影']" :class="{active:profile.interests?.includes(tag)}" @click="toggleInterest(tag)">{{tag}}</button></div></label><label>饮食、无障碍或其他需求<textarea v-model="profile.needs" maxlength="300" rows="3" placeholder="选填，只填写你希望助手在规划时考虑的内容"></textarea></label><button class="primary" :disabled="saving">保存旅行偏好</button><details v-if="Object.keys(feedback).length"><summary>管理推荐反馈</summary><div v-for="(value,key) in feedback" class="inline-row">{{key.replace('city:','')}} · {{({want:'想去',visited:'去过',hide:'不感兴趣'} as Record<string,string>)[value]}}<button type="button" @click="resetFeedback(String(key))">撤销</button></div></details></form>
 </template></main>

 <main v-else-if="page==='community'" class="page-container"><div class="detail-heading"><div><span class="small-label">STORIES ALONG THE WAY</span><h1>风景之外，还有故事。</h1><p>来自旅行者的照片与真实记录。</p></div><button class="primary" @click="writePost()">分享我的旅行 ↗</button></div><div class="personal-grid community-grid"><article v-for="post in feed" class="personal-card post-card"><button class="post-cover" @click="openPost(post.id)"><img v-if="post.images.length" :src="'/api/media/'+post.images[0]+'?thumb=true'" :alt="post.title"/><SceneryArt v-else theme="garden" label="旅行记录插画"/></button><small>{{post.city}} · {{post.travel_date||'旅行记录'}}</small><h3><button class="text-button" @click="openPost(post.id)">{{post.title}}</button></h3><p>{{post.body.slice(0,100)}}</p><div class="inline-row"><span>{{post.author}}</span><button class="text-button" @click="startFavorite('post',post.city,post.title,'post:'+post.id)">♡ 收藏游记</button></div></article></div><div v-if="!feed.length" class="community-empty"><span>✦</span><h2>第一段故事，等你写下</h2><p>公开内容审核通过后会出现在这里。也可以先把照片保存为私人足迹。</p><button class="outline" @click="writePost()">记录我的旅行</button></div></main>

 <main v-else-if="page==='admin'" class="page-container"><h1>内容管理</h1><p class="muted">公开内容先审核再展示，修改后重新进入审核。</p><div v-if="!isAdmin" class="empty-state">仅管理员可以访问。</div><template v-else><section class="knowledge-manager"><h2>RAG 知识库</h2><p class="muted">资料保存到数据库，分块后通过中文双字切分与 FTS5/BM25 检索，供助手和行程生成引用。请录入有权使用且核实过的资料。</p><form class="profile-form" @submit.prevent="addKnowledge"><div class="form-grid"><label>资料标题<input v-model="knowledgeForm.title" required maxlength="120"/></label><label>适用城市（空白为通用）<input v-model="knowledgeForm.city" maxlength="30"/></label><label>来源名称<input v-model="knowledgeForm.source" required maxlength="120"/></label><label>来源链接（选填）<input v-model="knowledgeForm.url" type="url"/></label></div><label>导入 Markdown / 文本<input type="file" accept=".md,.txt" @change="importKnowledge"/></label><label>资料正文<textarea v-model="knowledgeForm.body" required minlength="20" maxlength="100000" rows="7"></textarea></label><button class="primary" :disabled="saving">保存并建立索引</button></form><details><summary>查看 {{knowledgeDocuments.length}} 份资料</summary><article v-for="doc in knowledgeDocuments" class="knowledge-row"><div><b>{{doc.title}}</b><small>{{doc.city||'通用'}} · {{doc.source}} · {{doc.characters}}字</small></div><button @click="deleteKnowledge(doc.id)">移除</button></article></details></section><h2>待审核 {{adminQueue.posts.length}}</h2><article v-for="post in adminQueue.posts" class="review-card"><h3>{{post.title}} · {{post.city}}</h3><p>{{post.body}}</p><div class="photo-strip"><img v-for="uid in post.images" :src="'/api/media/'+uid+'?thumb=true'" :alt="post.title"/></div><button @click="review(post.id,'approved')">通过并公开</button><button @click="review(post.id,'rejected')">拒绝</button></article><h2>举报处理 {{adminQueue.reports.length}}</h2><article v-for="r in adminQueue.reports" class="review-card"><h3>{{r.title}}</h3><p>{{r.reason}}</p><button @click="openPost(r.post_id)">查看内容</button><button @click="review(r.post_id,'hidden')">下架并结案</button><button @click="review(r.post_id,'approved')">保留并结案</button></article><p v-if="!adminQueue.posts.length&&!adminQueue.reports.length" class="empty-state">暂时没有需要处理的内容。</p></template></main>
 <main v-else-if="page==='share'" class="page-container"><div class="detail-heading"><div><span class="small-label">A JOURNEY SHARED WITH YOU</span><h1>{{shared?.title||'只读旅行方案'}}</h1><p>分享为生成时的方案快照，不包含私人对话。</p></div><button @click="go('home')">发现我的下一站</button></div><JourneyBoard v-if="shareSession" :session="shareSession" :busy="false" readonly/></main>
 <main v-else class="empty-state"><h1>这条小路还没通向目的地</h1><button @click="go('home')">返回发现</button></main>

 <template v-if="page!=='workspace'&&page!=='share'"><button v-if="!widget" class="assistant-launcher" :style="floatingStyle" @pointerdown="startDrag" @click="launcherClick" title="可拖动；点击打开旅行助手" aria-label="打开旅行助手"><span>✦</span><div>旅行助手<small>聊聊你的下一站</small></div><b>↗</b></button><div v-else class="assistant-widget" :style="floatingStyle"><TravelConversation @drag="startDrag" @reset="resetFloating" :session="session" :busy="busy" widget @send="text=>send(text,false)" @generate="generate" @edit="editPreferences" @close="widget=false"/></div></template>

 <el-dialog v-model="authOpen" :title="register?'创建旅行账户':'欢迎回来'" width="min(440px,94vw)"><form class="dialog-form" @submit.prevent="authenticate"><p class="muted">收藏风景、保存行程，让每次出发都有迹可循。</p><label v-if="register">昵称<input v-model="credentials.name" required maxlength="30" autocomplete="nickname"/></label><label>邮箱<input type="email" v-model="credentials.email" required autocomplete="email"/></label><label>密码<input type="password" v-model="credentials.password" required minlength="8" maxlength="128" :autocomplete="register?'new-password':'current-password'"/></label><small v-if="register">至少8位字符。此版本使用邮箱作为账号，尚未接入邮件验证与密码找回。</small><button class="primary" :disabled="saving">{{saving?'请稍候…':register?'创建账户':'登录'}}</button><button type="button" class="text-button" @click="register=!register">{{register?'已有账户？去登录':'还没有账户？创建一个'}}</button></form></el-dialog>
 <el-dialog v-model="editor" title="确认你的旅行需求" width="min(580px,94vw)"><form class="dialog-form" @submit.prevent="savePreferences"><div class="form-grid"><label>出发城市<input v-model="form.departure_city" required maxlength="30"/></label><label>目的地<input v-model="form.destination" required maxlength="30"/></label><label>总预算（元）<input type="number" v-model.number="form.budget" required min="1" max="1000000"/></label><label>出行人数<input type="number" v-model.number="form.num_travelers" required min="1" max="10"/></label><label>出发日期<input type="date" v-model="form.start_date" required/></label><label>旅行天数<input type="number" v-model.number="form.days" required min="1" max="30"/></label><label>行程节奏<select v-model="form.pace"><option>轻松</option><option>适中</option><option>紧凑</option></select></label><label>交通偏好<select v-model="form.transport"><option>高铁优先</option><option>飞机优先</option><option>自驾</option></select></label></div><label>其他需求<textarea v-model="form.needs" maxlength="300"></textarea></label><p v-if="form.selected_spots?.length" class="muted">已选景点：{{form.selected_spots.join('、')}}</p><button class="primary" :disabled="busy">保存并确认需求</button></form></el-dialog>
 <el-dialog v-model="favoriteOpen" title="收藏这处风景" width="min(420px,94vw)"><form class="dialog-form" @submit.prevent="saveFavorite"><h3>{{pendingFavorite?.name}}</h3><label>放入收藏夹<select v-model="favoriteFolder" required><option v-for="f in folders" :value="f.id">{{f.name}}</option></select></label><div class="inline-row"><input v-model="folderName" placeholder="新建收藏夹" aria-label="新建收藏夹"/><button type="button" @click="createFolder">新建</button></div><button class="primary" :disabled="saving||!favoriteFolder">确认收藏</button></form></el-dialog>
 <el-dialog v-model="postOpen" :title="editingPost?'编辑旅行足迹':'留住这次旅行'" width="min(690px,96vw)" :close-on-click-modal="false"><form class="dialog-form" @submit.prevent="savePost(true)"><label>标题<input v-model="postForm.title" required maxlength="80" placeholder="给这段旅程起个名字"/></label><div class="form-grid"><label>城市<input v-model="postForm.city" required maxlength="30"/></label><label>旅行 / 拍摄日期<input type="date" v-model="postForm.travel_date" :max="new Date().toLocaleDateString('en-CA')"/></label></div><label>旅行记录<textarea v-model="postForm.body" required rows="5" maxlength="5000" placeholder="记录沿途风景、体验与实用建议…"></textarea></label><div class="photo-strip"><div v-for="(uid,i) in postForm.images"><img :src="'/api/media/'+uid+'?thumb=true'" alt="待发布旅行照片"/><button type="button" aria-label="移除照片" @click="postForm.images.splice(i,1)">×</button></div></div><label class="upload-zone">＋ 添加旅行照片 <small>JPEG / PNG / WebP · 单张8MB以内 · 最多9张</small><input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="uploadFiles" :disabled="uploadProgress!==null"/></label><p v-if="uploadProgress!==null">正在上传 {{uploadProgress}}%</p><p v-if="photoError" class="inline-error">{{photoError}} <button type="button" @click="retryUpload">重试</button></p><small class="muted">请上传有权使用的照片。系统去除照片中的 GPS 等元数据；拍摄日期由你填写。</small><label>可见范围<select v-model="postForm.visibility"><option value="private">仅自己可见</option><option value="public">公开（审核后展示）</option></select></label><div class="inline-row"><button type="button" :disabled="saving||uploadProgress!==null" @click="savePost(false)">保存草稿</button><button class="primary" :disabled="saving||uploadProgress!==null">{{postForm.visibility==='public'?'提交公开审核':'保存私人足迹'}}</button></div></form></el-dialog>
 <el-dialog v-model="shareOpen" title="分享这段旅行" width="min(520px,94vw)"><div class="dialog-form"><p>生成只读链接，有效期7天。分享包含当前方案快照，不包含聊天记录和账户资料。</p><button class="primary" :disabled="saving" @click="createShare">生成 / 更新分享链接</button><input v-if="shareUrl" readonly :value="shareUrl" aria-label="行程分享链接"/><button v-if="shareUrl" @click="copyShare">复制链接</button><button class="text-button danger" @click="revokeShare">撤销此行程的全部分享</button></div></el-dialog>
 <el-dialog :model-value="!!postDetail" @close="postDetail=null" :title="postDetail?.title" width="min(760px,96vw)"><template v-if="postDetail"><p>{{postDetail.author}} · {{postDetail.city}} · 拍摄日期 {{postDetail.travel_date||'未填写'}} / 发布于 {{new Date(postDetail.created*1000).toLocaleDateString()}}</p><div class="story-images"><img v-for="uid in postDetail.images" :src="'/api/media/'+uid" :alt="postDetail.title"/></div><p class="story-body">{{postDetail.body}}</p><button @click="startFavorite('post',postDetail.city,postDetail.title,'post:'+postDetail.id)">♡ 收藏游记</button><details><summary>举报这篇内容</summary><div class="dialog-form"><textarea v-model="reportReason" minlength="2" maxlength="300" placeholder="请描述举报原因"></textarea><button :disabled="reportReason.trim().length<2||saving" @click="report">提交举报</button></div></details></template></el-dialog>
 </div>
</template>
